B.ahZ=s(["\ubb34\ub8cc \uccb4\ud5d8\uc740 \uae30\uae30 \ud55c \ub300\uc5d0 \ud55c \ubc88, 72\uc2dc\uac04\uc774\uc5d0\uc694. \uc774\uc6a9\uc790\uac00 \uccb4\ud5d8 \uc2dc\uc791\uc744 \ub204\ub978 \ub54c\ubd80\ud130 \uc2dc\uac04\uc774 \ud758\ub7ec\uc694.","\uccb4\ud5d8\uc744 \uc2dc\uc791\ud558\uba74 \ub05d\ub098\ub294 \ub0a0\uc9dc\uc640 \uc2dc\uac01\uc744 \ud654\uba74\uc5d0 \ubcf4\uc5ec \uc918\uc694.","iOS\uc5d0\uc11c\ub294 App Store\uc5d0\uc11c 0\uc6d0 \uccb4\ud5d8 \uc0c1\ud488\uc744 \ubc1b\uc544 \uccb4\ud5d8\uc744 \uc2dc\uc791\ud574\uc694. \uc774\ub54c \ub3c8\uc740 \ub0b4\uc9c0 \uc54a\uc544\uc694.","\uccb4\ud5d8\uc740 \uc800\uc808\ub85c \uc720\ub8cc\ub85c \ubc14\ub00c\uc9c0 \uc54a\uc544\uc694.","\uccb4\ud5d8\uc774 \ub05d\ub098\uba74 \uc774\uc6a9\uad8c \uc5c6\uc774\ub294 \uc0c8 \ud559\uc2b5\uc744 \uc2dc\uc791\ud560 \uc218 \uc5c6\uc5b4\uc694.","\uccb4\ud5d8\uc774 \ub05d\ub098\ub3c4 \ud559\uc2b5 \uae30\ub85d \ubcf4\uae30, \ub0b4\ubcf4\ub0b4\uae30, \uc0ad\uc81c, \uad6c\ub9e4 \ubcf5\uc6d0, \ubb38\uc758\ub294 \uacc4\uc18d \uc4f8 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aHD=new A.em("\uc81c6\uc870 (\ubb34\ub8cc \uccb4\ud5d8)",B.ahZ)
B.agE=s(["\uc774\uc6a9\uad8c\uc740 29,900\uc6d0\uc774\uace0 \ud55c \ubc88\ub9cc \uacb0\uc81c\ud574\uc694. \uc790\ub3d9 \uacb0\uc81c\ub098 \uad6c\ub3c5\uc740 \uc5c6\uc5b4\uc694.","\uc2e4\uc81c \uacb0\uc81c \uae08\uc561\uc740 \uad6c\ub9e4 \ud654\uba74\uacfc \uc2a4\ud1a0\uc5b4 \uacb0\uc81c \ucc3d\uc5d0 \ud45c\uc2dc\ub3fc\uc694.","\uc774\uc6a9\uad8c\uc740 App Store \ub610\ub294 Google Play \uacb0\uc81c\ub85c \uc0ac\uc694. \uacb0\uc81c\ub294 \uac01 \uc2a4\ud1a0\uc5b4\uc758 \uc808\ucc28\ub97c \ub530\ub77c\uc694.","\uc571\uc744 \ub2e4\uc2dc \uc124\uce58\ud558\uac70\ub098 \ub2e4\ub978 \uae30\uae30\uc5d0\uc11c \uc4f8 \ub54c\ub294 \uac19\uc740 \uc2a4\ud1a0\uc5b4 \uacc4\uc815\uc73c\ub85c \uad6c\ub9e4 \ubcf5\uc6d0\uc744 \ud558\uba74 \ub3fc\uc694.","iOS, Android, \uc6f9 \uc0ac\uc774\uc5d0\ub294 \uc774\uc6a9\uad8c\uc774 \uacf5\uc720\ub418\uc9c0 \uc54a\uc544\uc694.","\uc6f9\uc5d0\uc11c\ub294 \uc774\uc6a9\uad8c\uc744 \ud314\uc9c0 \uc54a\uc544\uc694."],t.s)
B.aHS=new A.em("\uc81c7\uc870 (\uc774\uc6a9\uad8c \uad6c\ub9e4)",B.agE)
B.ahv=s(["\uc774\uc6a9\uad8c\uc744 \uc0b0 \ub4a4 \uc774\uc6a9\uc744 \uc2dc\uc791\ud558\uc9c0 \uc54a\uc558\ub2e4\uba74, \uad6c\ub9e4 \ub0b4\uc6a9 \ud655\uc778(\uc2a4\ud1a0\uc5b4 \uc601\uc218\uc99d \ub4f1)\uc744 \ubc1b\uc740 \ub0a0\ubd80\ud130 7\uc77c \uc548\uc5d0 \uccad\uc57d\ucca0\ud68c\ub97c \ud560 \uc218 \uc788\uc5b4\uc694(\uc804\uc790\uc0c1\uac70\ub798\ubc95 \uc81c17\uc870 \uc81c1\ud56d).","\uc774\uc6a9\uc744 \uc2dc\uc791\ud55c \ub514\uc9c0\ud138 \ucf58\ud150\uce20\ub294 \uccad\uc57d\ucca0\ud68c\uac00 \uc81c\ud55c\ub3fc\uc694. \ud68c\uc0ac\ub294 \ubb34\ub8cc \uccb4\ud5d8\uc744 \uc81c\uacf5\ud558\uace0 \uad6c\ub9e4 \ud654\uba74\uc5d0 \uc774 \uc0ac\uc2e4\uc744 \uc54c\ub824, \ubc95\uc774 \uc815\ud55c \uc870\uce58\ub97c \ud588\uc5b4\uc694(\uc804\uc790\uc0c1\uac70\ub798\ubc95 \uc81c17\uc870 \uc81c2\ud56d \uc81c5\ud638, \uc81c6\ud56d, \uac19\uc740 \ubc95 \uc2dc\ud589\ub839 \uc81c21\uc870\uc7582).","\ub2e4\ub9cc \uc774\uc6a9\uad8c\uc758 \ub0b4\uc6a9\uc774 \ud45c\uc2dc\xb7\uad11\uace0\uc640 \ub2e4\ub974\uac70\ub098 \uacc4\uc57d\uacfc \ub2e4\ub974\uac8c \uc81c\uacf5\ub410\ub2e4\uba74, \uacf5\uae09\ubc1b\uc740 \ub0a0\ubd80\ud130 3\uac1c\uc6d4 \uc548\uc5d0, \uadf8 \uc0ac\uc2e4\uc744 \uc548 \ub0a0 \ub610\ub294 \uc54c \uc218 \uc788\uc5c8\ub358 \ub0a0\ubd80\ud130 30\uc77c \uc548\uc5d0 \uccad\uc57d\ucca0\ud68c\ub97c \ud560 \uc218 \uc788\uc5b4\uc694(\uc804\uc790\uc0c1\uac70\ub798\ubc95 \uc81c17\uc870 \uc81c3\ud56d).","\ud658\ubd88\uc740 App Store \uad6c\ub9e4 \ub0b4\uc5ed\uc758 \ud658\ubd88 \uc694\uccad\uc774\ub098 Google Play \ud658\ubd88 \uc694\uccad\uc73c\ub85c \uc2e0\uccad\ud558\uac70\ub098, support@sunworks.kr\ub85c \ubb38\uc758\ud574 \uc8fc\uc138\uc694. \ud68c\uc0ac\ub294 \uc2a4\ud1a0\uc5b4 \ud658\ubd88 \uc808\ucc28\ub97c \uc548\ub0b4\ud558\uace0 \ud544\uc694\ud55c \uc870\uce58\ub97c \ub3c4\uc640\uc694."],t.s)
B.aHN=new A.em("\uc81c8\uc870 (\uccad\uc57d\ucca0\ud68c)",B.ahv)
B.aiz=s(["\ub9cc 19\uc138 \ubbf8\ub9cc \ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778(\ubcf4\ud638\uc790) \ub3d9\uc758 \uc5c6\uc774 \uc774\uc6a9\uad8c\uc744 \uc0c0\ub2e4\uba74, \ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc774\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uad6c\ub9e4\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\uc5b4\uc694(\ubbfc\ubc95 \uc81c5\uc870).","\ub2e4\ub9cc \ubbf8\uc131\ub144\uc790\uac00 \uc18d\uc784\uc218\ub85c \uc790\uc2e0\uc744 \uc131\ub144\uc790\ub85c \ubbff\uac8c \ud558\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \uc788\ub294 \uac83\ucc98\ub7fc \ubbff\uac8c \ud55c \uacbd\uc6b0(\ubbfc\ubc95 \uc81c17\uc870), \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ucc98\ubd84\uc744 \ud5c8\ub77d\ud55c \uc7ac\uc0b0\uc758 \ubc94\uc704 \uc548\uc5d0\uc11c \uc0b0 \uacbd\uc6b0(\ubbfc\ubc95 \uc81c6\uc870)\uc5d0\ub294 \ucde8\uc18c\uac00 \uc81c\ud55c\ub420 \uc218 \uc788\uc5b4\uc694.","\ucde8\uc18c\ub294 \uc81c8\uc870\uc640 \uac19\uc740 \ubc29\ubc95(\uc2a4\ud1a0\uc5b4 \ud658\ubd88 \uc694\uccad \ub610\ub294 \ubb38\uc758)\uc73c\ub85c \uc694\uccad\ud560 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aHQ=new A.em("\uc81c9\uc870 (\ubbf8\uc131\ub144\uc790\uc758 \uad6c\ub9e4)",B.aiz)
B.ahV=s(["\uc798\ubabb \uacb0\uc81c\ub418\uac70\ub098 \ub354 \uacb0\uc81c\ub41c \uae08\uc561(\uacfc\uc624\uae08)\uc774 \uc788\uc73c\uba74 \ud68c\uc0ac\ub294 \uc774\ub97c \ub3cc\ub824\uc918\uc694(\ucf58\ud150\uce20\uc0b0\uc5c5 \uc9c4\ud765\ubc95 \uc81c28\uc870).","\uc2a4\ud1a0\uc5b4\uc5d0\uc11c \uacb0\uc81c\ud55c \uae08\uc561\uc740 \uc2a4\ud1a0\uc5b4 \ud658\ubd88 \uc808\ucc28\ub85c \ub3cc\ub824\ubc1b\uc744 \uc218 \uc788\uace0, \ubb38\uc758\ud558\uba74 \ud68c\uc0ac\uac00 \ud544\uc694\ud55c \uc870\uce58\ub97c \ub3c4\uc640\uc694."],t.s)
B.aHJ=new A.em("\uc81c10\uc870 (\uacfc\uc624\uae08\uc758 \ud658\ubd88)",B.ahV)
B.as1=s(['\ucf58\ud150\uce20\uc5d0 \uc624\ub958\ub098 \uacb0\ud568\uc774 \uc788\uc73c\uba74 \ud68c\uc0ac\ub294 \uace0\uce58\uace0, \uace0\uce60 \uc218 \uc5c6\uc73c\uba74 \ud658\ubd88\ud574\uc694. \uc624\ub958\ub294 \ud559\uc2b5 \ud654\uba74\uc758 "\uc774\uc0c1\ud574\uc694" \ubc84\ud2bc\uc774\ub098 \ubb38\uc758\ub85c \uc54c\ub824 \uc8fc\uc138\uc694.',"\ud68c\uc0ac\uac00 \uc11c\ube44\uc2a4\ub97c \uc911\ub2e8\ud558\ub824\uba74 \uc911\ub2e8 30\uc77c \uc804\ubd80\ud130 \uc571\uacfc \uc6f9 \ud398\uc774\uc9c0\uc5d0 \uc54c\ub824\uc694.","\uc11c\ube44\uc2a4\ub97c \uc911\ub2e8\ud574\ub3c4, \uc774\ubbf8 \uae30\uae30\uc5d0 \uc124\uce58\ub41c \uc571\uc758 \ud559\uc2b5\uc740 \uac00\ub2a5\ud55c \ubc94\uc704\uc5d0\uc11c \uacc4\uc18d \uc4f8 \uc218 \uc788\uac8c \ud574\uc694."],t.s)
B.aHu=new A.em("\uc81c11\uc870 (\ucf58\ud150\uce20 \uacb0\ud568\uacfc \uc11c\ube44\uc2a4 \ubcc0\uacbd\xb7\uc911\ub2e8)",B.as1)
B.aeE=s(["\ud559\uc2b5 \uae30\ub85d\uc740 \uc774\uc6a9\uc790\uc758 \uae30\uae30\uc5d0\ub9cc \uc800\uc7a5\ub3fc\uc694. \uc571\uc744 \uc0ad\uc81c\ud558\uac70\ub098 \uae30\uae30\ub97c \uc783\uc5b4\ubc84\ub9ac\uac70\ub098 \ucd08\uae30\ud654\ud558\uba74 \ud68c\uc0ac\ub3c4 \uae30\ub85d\uc744 \ub418\uc0b4\ub9b4 \uc218 \uc5c6\uc5b4\uc694.",'\uae30\ub85d\uc744 \uc9c0\ud0a4\ub824\uba74 \uc124\uc815 \ud654\uba74\uc758 "\ud559\uc2b5 \uae30\ub85d \u2192 \ub0b4\ubcf4\ub0b4\uae30"\ub85c \ud30c\uc77c\uc744 \ub530\ub85c \ubcf4\uad00\ud574 \uc8fc\uc138\uc694.',"\ud68c\uc0ac\uc758 \uace0\uc758\ub098 \uacfc\uc2e4\ub85c \uae30\ub85d\uc774 \uc190\uc0c1\ub418\uac70\ub098 \uc190\ud574\uac00 \uc0dd\uae30\uba74 \ud68c\uc0ac\uac00 \ucc45\uc784\uc838\uc694."],t.s)
B.aHV=new A.em("\uc81c12\uc870 (\ud559\uc2b5 \uae30\ub85d)",B.aeE)
B.aeK=s(["\uc774\uc6a9\uc790\ub294 \ub2e4\uc74c \ud589\ub3d9\uc744 \ud558\uba74 \uc548 \ub3fc\uc694.","\xb7 \ucf58\ud150\uce20\ub97c \ud68c\uc0ac \ud5c8\ub77d \uc5c6\uc774 \ubcf5\uc81c, \ubc30\ud3ec, \ud310\ub9e4\ud558\uac70\ub098 \ub2e4\ub978 \uc11c\ube44\uc2a4\uc5d0 \uc4f0\ub294 \uc77c","\xb7 \uc571\uc744 \uc5ed\uc124\uacc4\ud558\uac70\ub098 \ubcc0\uc870\ud558\ub294 \uc77c","\xb7 \ubb34\ub8cc \uccb4\ud5d8\uc774\ub098 \uc774\uc6a9\uad8c\uc758 \uc81c\ud55c\uc744 \uc6b0\ud68c\ud558\ub294 \uc77c","\xb7 \uadf8 \ubc16\uc5d0 \ubc95\uc744 \uc5b4\uae30\uac70\ub098 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub97c \uce68\ud574\ud558\ub294 \uc77c"],t.s)
B.aHH=new A.em("\uc81c13\uc870 (\uc774\uc6a9\uc790\uc758 \uc758\ubb34)",B.aeK)
B.art=s(["\uc571\uacfc \ucf58\ud150\uce20\uc758 \uc800\uc791\uad8c \ub4f1 \uc9c0\uc2dd\uc7ac\uc0b0\uad8c\uc740 \ud68c\uc0ac \ub610\ub294 \uc815\ub2f9\ud55c \uad8c\ub9ac\uc790\uc5d0\uac8c \uc788\uc5b4\uc694.","\uc774\uc6a9\uad8c\uc740 \uac1c\uc778 \ud559\uc2b5\uc744 \uc704\ud574 \ucf58\ud150\uce20\ub97c \uc4f8 \uc218 \uc788\ub294 \uad8c\ub9ac\uc774\uace0, \ucf58\ud150\uce20\uc758 \uad8c\ub9ac\ub97c \ub118\uaca8\ubc1b\ub294 \uac83\uc740 \uc544\ub2c8\uc5d0\uc694.",'\uc571\uc5d0 \uc4f0\uc778 \uc624\ud508\uc18c\uc2a4 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc640 \uae00\uaf34\uc758 \ub77c\uc774\uc120\uc2a4\ub294 \uc571 \uc124\uc815\uc758 "\ub77c\uc774\uc120\uc2a4" \ud654\uba74\uc5d0\uc11c \ubcfc \uc218 \uc788\uc5b4\uc694.'],t.s)
B.aHU=new A.em("\uc81c14\uc870 (\uc9c0\uc2dd\uc7ac\uc0b0\uad8c)",B.art)
B.ahp=s(['\ud68c\uc0ac\ub294 \uac1c\uc778\uc815\ubcf4\ub97c \uac1c\uc778\uc815\ubcf4 \ucc98\ub9ac\ubc29\uce68\uc5d0 \ub530\ub77c \ub2e4\ub904\uc694. \ucc98\ub9ac\ubc29\uce68\uc740 \uc571 \uc124\uc815\uc758 "\uac1c\uc778\uc815\ubcf4 \ucc98\ub9ac\ubc29\uce68"\uacfc \uc6f9 \ud398\uc774\uc9c0(https://hanja-app.sunw.kr/privacy.html)\uc5d0\uc11c \ubcfc \uc218 \uc788\uc5b4\uc694.'],t.s)
B.aHR=new A.em("\uc81c15\uc870 (\uac1c\uc778\uc815\ubcf4)",B.ahp)
B.ahP=s(["\ubd88\ud3b8\ud55c \uc810\uc774\ub098 \ubd84\uc7c1\uc774 \uc788\uc73c\uba74 \uba3c\uc800 \uc544\ub798\ub85c \uc54c\ub824 \uc8fc\uc138\uc694.","\xb7 \uc774\uba54\uc77c: support@sunworks.kr","\xb7 \uc804\ud654: 070-8717-8850","\ud68c\uc0ac\uc640 \uc774\uc57c\uae30\ub85c \ud574\uacb0\ub418\uc9c0 \uc54a\uc73c\uba74 \ucf58\ud150\uce20\ubd84\uc7c1\uc870\uc815\uc704\uc6d0\ud68c(www.kcdrc.kr)\uc5d0 \uc870\uc815\uc744 \uc2e0\uccad\ud560 \uc218 \uc788\uc5b4\uc694.","\uc18c\uc1a1\uc774 \ud544\uc694\ud558\uba74 \uad00\ud560 \ubc95\uc6d0\uc740 \ubbfc\uc0ac\uc18c\uc1a1\ubc95\uc5d0 \ub530\ub77c \uc815\ud574\uc694. \uc774 \uc57d\uad00\uc740 \ub300\ud55c\ubbfc\uad6d \ubc95\uc744 \ub530\ub77c\uc694."],t.s)
B.aHT=new A.em("\uc81c16\uc870 (\ubd84\uc7c1 \ud574\uacb0)",B.ahP)
B.are=s(["\uc774 \uc57d\uad00\uc740 2026\ub144 10\uc6d4 17\uc77c\ubd80\ud130 \uc2dc\ud589\ud574\uc694(\ubc84\uc804 1.0)."],t.s)
B.aHK=new A.em("\ubd80\uce59",B.are)
B.aeJ=s([B.aHM,B.aHt,B.aHI,B.aHz,B.aHO,B.aHD,B.aHS,B.aHN,B.aHQ,B.aHJ,B.aHu,B.aHV,B.aHH,B.aHU,B.aHR,B.aHT,B.aHK],t.jZ)
B.aHq=new A.Tu("\uc774\uc6a9\uc57d\uad00","2026\ub144 10\uc6d4 17\uc77c",B.aeJ,null)
B.adY=s(["\uc774 \uc571\uc758 \ud559\uc2b5 \uae30\ub2a5\uc740 \uc774\ub984, \uc804\ud654\ubc88\ud638, \uc774\uba54\uc77c \uc8fc\uc18c \uac19\uc740 \uac1c\uc778\uc815\ubcf4\ub97c \ubaa8\uc73c\uc9c0 \uc54a\uc544\uc694. \uc9c1\uc811 \ubcf4\ub0b4\ub294 \ubb38\uc758\ub294 10\uc808\uc5d0\uc11c \uc124\uba85\ud574\uc694.","\ud68c\uc6d0\uac00\uc785\ub3c4 \ub85c\uadf8\uc778\ub3c4 \uc5c6\uc5b4\uc694. \uacf5\ubd80\ud55c \uae30\ub85d\uc740 \uc5ec\ub7ec\ubd84\uc758 \uae30\uae30 \uc548\uc5d0\ub9cc \ub0a8\uc544\uc694.","\uc6b0\ub9ac\ub294 \uadf8 \uae30\ub85d\uc744 \ubcfc \uc218 \uc5c6\uace0, \ub2e4\ub978 \uacf3\uc73c\ub85c \ubcf4\ub0b4\uc9c0\ub3c4 \uc54a\uc544\uc694.","\uc5f0\uad6c\uc5d0 \ucc38\uc5ec\ud558\uae30\ub85c \ud55c \uacbd\uc6b0\uc5d0\ub9cc, \ud559\uc2b5 \ud69f\uc218\ub97c \ubaa8\uc740 \ud30c\uc77c\uc744 \uc9c1\uc811 \ubcf4\ub0bc \uc218 \uc788\uc5b4\uc694(9\uc808)."],t.s)
B.aHG=new A.em("\ud55c\ub208\uc5d0 \ubcf4\uae30",B.adY)
B.ac5=s(["\ud559\uc2b5 \uae30\ub2a5\uc740 \uac1c\uc778\uc815\ubcf4\ub97c \ubaa8\uc73c\uac70\ub098 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc8fc\uc9c0 \uc54a\uc544\uc694. \uc5f0\uad6c \ucc38\uc5ec\xb7\uc758\uacac \ubcf4\ub0b4\uae30\xb7\ubb38\ud56d \uc2e0\uace0\uc5d0\uc11c \uc9c1\uc811 \ubcf4\ub0b4\ub294 \uc815\ubcf4\ub294 \uc544\ub798\uc5d0\uc11c \ub530\ub85c \uc124\uba85\ud574\uc694.","\uad11\uace0\ub3c4 \uc5c6\uace0, \uc0ac\uc6a9\uc790\ub97c \ub530\ub77c\ub2e4\ub2c8\uba70 \uae30\ub85d\ud558\ub294 \ucd94\uc801 \ub3c4\uad6c\ub3c4 \ub123\uc9c0 \uc54a\uc558\uc5b4\uc694.","\uc5f0\uad6c \ucc38\uc5ec\uc790\uac00 \uc9c1\uc811 \ubcf4\ub0b4 \uc900 \uc9d1\uacc4 \ud30c\uc77c\uc740 9\uc808\uc5d0\uc11c \ub530\ub85c \uc124\uba85\ud574\uc694.","\uc758\uacac \ubcf4\ub0b4\uae30\ub85c \uc9c1\uc811 \uc801\uc5b4 \ubcf4\ub0b8 \uc774\ub984 \ub610\ub294 \ubcc4\uce6d, \uc774\uba54\uc77c\uacfc \ubb38\uc758 \ub0b4\uc6a9\uc740 10\uc808\uc5d0\uc11c \ub530\ub85c \uc124\uba85\ud574\uc694."],t.s)
B.aHC=new A.em("1. \uc6b0\ub9ac\uac00 \ubaa8\uc73c\ub294 \uac1c\uc778\uc815\ubcf4",B.ac5)
B.awe=s(["\uc5b4\ub5a4 \ud55c\uc790\ub97c \uc5b8\uc81c \ub9de\ud614\ub294\uc9c0, \uba70\uce60 \uc5f0\uc18d\uc73c\ub85c \uacf5\ubd80\ud588\ub294\uc9c0 \uac19\uc740 \ud559\uc2b5 \uae30\ub85d\uc740 \uc571\uc744 \uc124\uce58\ud55c \uae30\uae30 \uc548\uc5d0\ub9cc \uc800\uc7a5\ub3fc\uc694.","\ud734\ub300\uc804\ud654\uc640 \ud0dc\ube14\ub9bf\ucc98\ub7fc \uae30\uae30\uac00 \uc5ec\ub7ec \ub300\uba74 \uae30\ub85d\uc740 \uc11c\ub85c \ub530\ub85c \uc313\uc5ec\uc694. \uae30\uae30\ub07c\ub9ac \uae30\ub85d\uc744 \ud569\uce58\ub294 \uae30\ub2a5\uc740 \uc544\uc9c1 \uc5c6\uc5b4\uc694.","\uc6f9 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc4f0\uba74 \uae30\ub85d\uc740 \uadf8 \ube0c\ub77c\uc6b0\uc800\uc758 \uc800\uc7a5 \uacf5\uac04\uc5d0 \ub0a8\uc544\uc694. \ube0c\ub77c\uc6b0\uc800 \uae30\ub85d\uc744 \uc9c0\uc6b0\uac70\ub098 \uc2dc\ud06c\ub9bf \ubaa8\ub4dc\ub85c \uc5f4\uba74 \ud559\uc2b5 \uae30\ub85d\ub3c4 \uc0ac\ub77c\uc9c8 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aHy=new A.em("2. \ud559\uc2b5 \uae30\ub85d\uc740 \uc5b4\ub514\uc5d0 \uc800\uc7a5\ub418\ub098\uc694",B.awe)
B.ank=s(['\uc815\ud574 \ub454 \uc2dc\uac04\uc5d0 "\uacf5\ubd80\ud560 \uc2dc\uac04\uc774\uc57c"\ub77c\uace0 \uc54c\ub824 \uc8fc\uae30 \uc704\ud574\uc11c\ub9cc \uc368\uc694. \uc2dc\ud5d8 \ub0a0\uc9dc\uac00 \ub2e4\uac00\uc624\uba74 \ub0a8\uc740 \ub0a0\uc744 \uc54c\ub824 \uc8fc\ub294 \ub370\uc5d0\ub3c4 \uc368\uc694.',"\uc54c\ub9bc\uc740 \uae30\uae30 \uc548\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc838\uc694. \uc54c\ub9bc\uc744 \ub9cc\ub4e4\ub824\uace0 \uc678\ubd80 \uc11c\ubc84\uc5d0 \ubb34\uc5b8\uac00\ub97c \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694.","\uc54c\ub9bc\uc744 \ubc1b\uace0 \uc2f6\uc9c0 \uc54a\uc73c\uba74 \uc124\uc815\uc5d0\uc11c \ub044\uac70\ub098, \uae30\uae30\uc758 \uc54c\ub9bc \uad8c\ud55c\uc744 \uaebc\ub3c4 \uc571\uc740 \uadf8\ub300\ub85c \uc4f8 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aHB=new A.em("3. \uc54c\ub9bc \uad8c\ud55c\uc740 \uc65c \ud544\uc694\ud55c\uac00\uc694",B.ank)
B.aiH=s(["iPhone\uc758 iCloud \ubc31\uc5c5\uc774\ub098 Android\uc758 \uc790\ub3d9 \ubc31\uc5c5\uc744 \ucf1c \ub450\uba74, \uc6b4\uc601\uccb4\uc81c\uac00 \uc571 \ub370\uc774\ud130\ub97c \ubc31\uc5c5\uc5d0 \ud568\uaed8 \ub2f4\uc744 \uc218 \uc788\uc5b4\uc694.","\uc774 \ubc31\uc5c5\uc740 \uc560\ud50c\uc774\ub098 \uad6c\uae00\uc774 \uc5ec\ub7ec\ubd84\uc758 \uacc4\uc815\uc5d0\uc11c \uad00\ub9ac\ud558\ub294 \uac83\uc774\uace0, \uc6b0\ub9ac\uac00 \uadf8 \ub0b4\uc6a9\uc744 \ubcf4\uac70\ub098 \uac00\uc838\uc62c \uc218\ub294 \uc5c6\uc5b4\uc694.","\ubc31\uc5c5\uc5d0 \ub2f4\uae30\uc9c0 \uc54a\uac8c \ud558\ub824\uba74 \uae30\uae30 \uc124\uc815\uc5d0\uc11c \uc774 \uc571\uc758 \ubc31\uc5c5\uc744 \uaebc \uc8fc\uc138\uc694."],t.s)
B.aHP=new A.em("4. \uae30\uae30 \uc790\ub3d9 \ubc31\uc5c5",B.aiH)
B.anb=s(["\uc571\uc740 \uc2dc\ud5d8 \uc77c\uc815\uacfc \ud559\uc2b5 \uc790\ub8cc\ub97c \ucd5c\uc2e0\uc73c\ub85c \uc720\uc9c0\ud558\ub824\uace0 \uc815\ud574\uc9c4 \uc8fc\uc18c\uc5d0\uc11c \ubc84\uc804 \ubaa9\ub85d\uacfc \ubc14\ub010 \uc790\ub8cc\ub97c \ub0b4\ub824\ubc1b\uc544\uc694. \uc790\ub8cc\uc5d0\ub294 \ud55c\uc790\xb7\uc774\uc57c\uae30\xb7\uadf8\ub9bc\xb7\uc74c\uc131\uc774 \ud3ec\ud568\ub420 \uc218 \uc788\uc5b4\uc694. \ubc1b\uc740 \uc790\ub8cc\ub294 \uae30\uae30\uc5d0 \uc800\uc7a5\ud574 \uc778\ud130\ub137 \uc5c6\uc774\ub3c4 \uc4f8 \uc218 \uc788\uc5b4\uc694. \uc6f9\uc5d0\uc11c\ub294 \uc0c8 \ubc84\uc804\uc774 \ub098\uc654\ub294\uc9c0 \ud655\uc778\ud558\ub294 \ud30c\uc77c\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc694.",'\uc774\ub54c \ubcf4\ub0b4\ub294 \uac74 "\uadf8 \ud30c\uc77c\uc744 \uc8fc\uc138\uc694"\ub77c\ub294 \uc694\uccad\ubfd0\uc774\uc5d0\uc694. \ud559\uc2b5 \uae30\ub85d\uc774\ub098 \uae30\uae30 \uc548\uc758 \uc815\ubcf4\ub294 \ud568\uaed8 \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694.',"\ub2e4\ub9cc \uc778\ud130\ub137 \uc694\uccad\uc740 \uadf8 \ud30c\uc77c\uc744 \ubcf4\uad00\ud558\ub294 \ud638\uc2a4\ud305 \ud68c\uc0ac\uc758 \uc11c\ubc84\ub97c \uac70\uce58\uae30 \ub54c\ubb38\uc5d0, \uc811\uc18d \uc2dc\uac01\uacfc IP \uc8fc\uc18c \uac19\uc740 \uc811\uc18d \uae30\ub85d\uc774 \uadf8 \ud68c\uc0ac \ucabd\uc5d0 \uc7a0\uc2dc \ub0a8\uc744 \uc218 \uc788\uc5b4\uc694. \uc774 \uae30\ub85d\uc740 \uc6b0\ub9ac\uac00 \ub9cc\ub4e4\uc9c0\ub3c4 \ubcf4\uad00\ud558\uc9c0\ub3c4 \uc54a\uc544\uc694."],t.s)
B.aHs=new A.em("5. \uc778\ud130\ub137\uc744 \uc4f0\ub294 \uc21c\uac04",B.anb)
B.aoy=s(['"\uc790\ub791\ud558\uae30"\uc5d0\uc11c \ub9cc\ub4e0 \uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\ub098 \ud559\uc2b5 \uae30\ub85d \ud30c\uc77c\uc740 \uc5ec\ub7ec\ubd84\uc774 \uc9c1\uc811 \ub0b4\ubcf4\ub0bc \ub54c\ub9cc \uae30\uae30 \ubc16\uc73c\ub85c \ub098\uac00\uc694.',"\ub0b4\ubcf4\ub0b4\uae30\ub97c \ub204\ub974\uba74 \uae30\uae30\uc758 \uacf5\uc720 \ucc3d\uc774 \uc5f4\ub9ac\uace0, \uac70\uae30\uc11c \uace0\ub978 \uc571(\uba54\uc2dc\uc9c0, \uc0ac\uc9c4\ucca9 \ub4f1)\uc73c\ub85c\ub9cc \uc804\ub2ec\ub3fc\uc694. \uc6b0\ub9ac \uc11c\ubc84\ub85c\ub294 \uc544\ubb34\uac83\ub3c4 \uac00\uc9c0 \uc54a\uc544\uc694.","\uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\uc5d0\ub294 \uc774\ub984\uc774\ub098 \uc5f0\ub77d\ucc98\uac00 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uc544\uc694."],t.s)
B.aHL=new A.em("6. \uae30\ub85d\uc744 \ub0b4\ubcf4\ub0bc \ub54c",B.aoy)
B.aqo=s(["\ud559\uc2b5 \uae30\ub85d\uc740 \uc5ec\ub7ec\ubd84\uc774 \uc9c0\uc6b8 \ub54c\uae4c\uc9c0 \uae30\uae30\uc5d0 \ub0a8\uc544\uc694. \uc6b0\ub9ac\uac00 \ub530\ub85c \uc815\ud55c \ubcf4\uad00 \uae30\uac04\uc740 \uc5c6\uc5b4\uc694.","\uae30\ub85d\uc744 \uc9c0\uc6b0\ub824\uba74 \ub450 \uac00\uc9c0 \ubc29\ubc95\uc774 \uc788\uc5b4\uc694.",'\xb7 \uc124\uc815 \ud654\uba74\uc758 "\ud559\uc2b5 \uae30\ub85d"\uc5d0\uc11c \uae30\ub85d \ucd08\uae30\ud654\ub97c \ub204\ub974\uba74 \ud559\uc2b5 \uae30\ub85d\uc774 \uc9c0\uc6cc\uc838\uc694.',"\xb7 \uc571\uc744 \uc0ad\uc81c\ud558\uba74 \uc571\uc774 \ub9cc\ub4e0 \ub370\uc774\ud130\uac00 \uae30\uae30\uc5d0\uc11c \ud568\uaed8 \uc0ac\ub77c\uc838\uc694.","\uae30\uae30 \uc790\ub3d9 \ubc31\uc5c5\uc5d0 \uc774\ubbf8 \ub2f4\uae34 \ub0b4\uc6a9\uc740 \uae30\uae30 \uc124\uc815\uc758 \ubc31\uc5c5 \uad00\ub9ac\uc5d0\uc11c \uc9c0\uc6cc \uc8fc\uc138\uc694."],t.s)
B.aHx=new A.em("7. \ubcf4\uad00 \uae30\uac04\uacfc \uc9c0\uc6b0\ub294 \ubc29\ubc95",B.aqo)
B.aev=s(["\uc774 \uc571\uc740 \ucd08\ub4f1\ud559\uc0dd\uacfc \uc911\ud559\uc0dd\uc774 \ud55c\uc790\ub97c \uacf5\ubd80\ud558\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\uc5b4\uc694. \uac1c\uc778\uc815\ubcf4\ub97c \ubaa8\uc73c\uc9c0 \uc54a\uc73c\ub2c8 \uac00\uc785\ud560 \ub54c \ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \ubc1b\ub294 \uc808\ucc28\ub3c4 \uc5c6\uc5b4\uc694. \uc5f0\uad6c \ucc38\uc5ec\ub294 \uc608\uc678\uc608\uc694. \ubaa8\uc9d1\ud560 \ub54c \ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \uba3c\uc800 \ubc1b\uc544\uc694(9\uc808).","\ubcf4\ud638\uc790\uaed8\uc11c\ub294 \uc790\ub140\uc758 \uae30\uae30\uc5d0\uc11c \uc571 \uc124\uc815\uacfc \ud559\uc2b5 \uae30\ub85d\uc744 \uc9c1\uc811 \ud655\uc778\ud558\uace0 \uc9c0\uc6b8 \uc218 \uc788\uc5b4\uc694.","\ub098\uc911\uc5d0 \uacc4\uc815\uc774\ub098 \ub3d9\uae30\ud654 \uae30\ub2a5\uc774 \uc0dd\uaca8\uc11c \uac1c\uc778\uc815\ubcf4\ub97c \ub2e4\ub8e8\uac8c \ub418\uba74, \uadf8\ub54c\ub294 \ubc95\uc5d0 \ub530\ub77c \ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \uba3c\uc800 \ubc1b\uace0 \uc774 \ubc29\uce68\ub3c4 \ubbf8\ub9ac \uace0\uccd0\uc11c \uc54c\ub824 \ub4dc\ub9b4\uac8c\uc694."],t.s)
B.aHF=new A.em("8. \ub9cc 14\uc138 \ubbf8\ub9cc \uc5b4\ub9b0\uc774\uc640 \ubcf4\ud638\uc790\uc5d0\uac8c",B.aev)
B.amO=s(["\uc571\uc744 \ub354 \uc88b\uac8c \ub9cc\ub4e4\ub824\uace0, \uc6b4\uc601\uc790\uac00 \ubbf8\ub9ac \ubaa8\uc9d1\ud55c \ucc38\uc5ec\uc790\uc5d0\uac8c\uc11c\ub9cc \ud559\uc2b5 \ud69f\uc218\ub97c \ubaa8\uc740 \ud30c\uc77c\uc744 \ubc1b\uc544\uc694. \ucc38\uc5ec\ub294 \uc120\ud0dd\uc774\uace0, \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc571\uc758 \ubaa8\ub4e0 \uae30\ub2a5\uc744 \uadf8\ub300\ub85c \uc4f8 \uc218 \uc788\uc5b4\uc694.",'\ub9cc 14\uc138 \ubbf8\ub9cc \ucc38\uc5ec\uc790\ub294 \ubaa8\uc9d1\ud560 \ub54c \ubcf4\ud638\uc790(\ubc95\uc815\ub300\ub9ac\uc778)\uc5d0\uac8c \uba3c\uc800 \ub3d9\uc758\ub97c \ubc1b\uc544\uc694. \uc571\ub3c4 \ud30c\uc77c\uc744 \ubcf4\ub0b4\uae30 \uc804\uc5d0 "\ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \ubc1b\uc740 \ucc38\uc5ec\uc790\ub9cc" \ubcf4\ub0b4 \ub2ec\ub77c\uace0 \ud55c \ubc88 \ub354 \uc54c\ub824\uc694.',"\ud30c\uc77c\uc5d0 \ub2f4\uae30\ub294 \uac83\uc740 \uc6b4\uc601\uc790\uac00 \ub098\ub220 \uc900 \ucc38\uc5ec \ucf54\ub4dc, \ubaa9\ud45c \uae09\uc218, \uccab \ud559\uc2b5\uc77c\ubd80\ud130 \uba70\uce60\uc9f8\uc778\uc9c0\ub97c \uc13c \ub0a0\uc9dc \ubc88\ud638\uc640 \uadf8\ub0a0\uc758 \ud559\uc2b5 \uc2dc\uc791\xb7\uc644\ub8cc \uac19\uc740 \ub3d9\uc791 \ud69f\uc218, \uae09\uc218\ub97c \uc644\uc131\ud558\uac70\ub098 \ubaa8\uc758\uc2dc\ud5d8\uc5d0 \ucc98\uc74c \ud569\uaca9\ud55c \ub0a0\uacfc \ud30c\uc77c\uc744 \ub9cc\ub4e0 \ub0a0\uc758 \ub0a0\uc9dc \ubc88\ud638, \uce90\ub9ad\ud130 \ud45c\uc2dc \uc2e4\ud5d8 \ubc30\uc815\uac12(\ucf1c\uc9d0/\uaebc\uc9d0)\ubfd0\uc774\uc5d0\uc694. \uc2e4\uc81c \ub0a0\uc9dc\uc640 \uc2dc\uac01, \ub2f5\uc548, \ud55c\uc790\ubcc4 \uae30\ub85d, \uc774\ub984\uacfc \uc5f0\ub77d\ucc98, \uae30\uae30 \uc2dd\ubcc4\uac12\uc740 \ub2f4\uae30\uc9c0 \uc54a\uc544\uc694.",'\ud30c\uc77c\uc740 \uc124\uc815 \ud654\uba74\uc758 "\ud559\uc2b5 \uae30\ub85d \u2192 \uc5f0\uad6c \ucc38\uc5ec"\uc5d0\uc11c \uc9c1\uc811 \uacf5\uc720 \ucc3d\uc744 \uc5f4\uc5b4 \ubcf4\ub0bc \ub54c\ub9cc \uae30\uae30 \ubc16\uc73c\ub85c \ub098\uac00\uc694. \uc571\uc774 \uc800\uc808\ub85c \ubcf4\ub0b4\ub294 \uc77c\uc740 \uc5c6\uc5b4\uc694.','\ucc38\uc5ec \ucf54\ub4dc\ub294 \uae30\uae30 \uc548\uc5d0\ub9cc \uc800\uc7a5\ub418\uace0 \ud559\uc2b5 \uae30\ub85d \ubc31\uc5c5 \ud30c\uc77c\uc5d0\ub294 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uc544\uc694. "\uc5f0\uad6c \ucc38\uc5ec"\uc5d0\uc11c \uc9c0\uc6b0\uac70\ub098 \ud559\uc2b5 \uae30\ub85d\uc744 \ucd08\uae30\ud654\ud558\uba74 \ud568\uaed8 \uc9c0\uc6cc\uc838\uc694. \ubaa8\uc9d1\ud560 \ub54c \ubc1b\uc740 \uc5f0\ub77d\ucc98\ub294 \uc9d1\uacc4 \ud30c\uc77c\uacfc \ub530\ub85c \ubcf4\uad00\ud574\uc694. \ucc38\uc5ec \ucf54\ub4dc\uc640 \uc5f0\ub77d\ucc98\ub97c \uc787\ub294 \uba85\ub2e8\uc740 \uc6b4\uc601\uc790\ub9cc \ubd10\uc694. \uce90\ub9ad\ud130 \ud45c\uc2dc \uc2e4\ud5d8 \ubc30\uc815\uac12(\ucf1c\uc9d0/\uaebc\uc9d0)\uc740 \ucc38\uc5ec \ucf54\ub4dc\ub97c \uc9c0\uc6b0\uac70\ub098 \ud559\uc2b5 \uae30\ub85d\uc744 \ucd08\uae30\ud654\ud574\ub3c4 \uae30\uae30\uc5d0 \ub0a8\uc544\uc11c, \uac19\uc740 \ucf54\ub4dc\ub97c \ub2e4\uc2dc \ub123\uc73c\uba74 \uc6d0\ub798 \ubc30\uc815\uc73c\ub85c \ub3cc\uc544\uac00\uc694.',"\ubcf4\uad00 \uae30\uac04: \uc9d1\uacc4 \ud30c\uc77c\uc740 \uc5f0\uad6c\uac00 \ub05d\ub09c \ub4a4 1\ub144 \uc548\uc5d0 \uc9c0\uc6cc\uc694. \uc5f0\ub77d\ucc98\uc640 \ucc38\uc5ec \ucf54\ub4dc \uba85\ub2e8\uc740 \uc5f0\uad6c\uac00 \ub05d\ub098\uba74 \ubc14\ub85c \uc9c0\uc6cc\uc694. \ucc38\uc5ec\ub97c \uadf8\ub9cc\ub450\uac70\ub098 \ubcf4\ub0b8 \ud30c\uc77c\uc744 \uc9c0\uc6cc \ub2ec\ub77c\uace0 \ud558\ub824\uba74 \ucc38\uc5ec \ucf54\ub4dc\uc640 \ud568\uaed8 \uc544\ub798 \ubb38\uc758\ucc98\ub85c \uc54c\ub824 \uc8fc\uc138\uc694."],t.s)
B.aHA=new A.em("9. \uc5f0\uad6c \ucc38\uc5ec(\uc120\ud0dd)",B.amO)
B.abJ=s(['\uc124\uc815\uc758 "\uc758\uacac \ubcf4\ub0b4\uae30"\ub098 \uc774\uc6a9\uad8c \ud654\uba74\uc758 "\ubb38\uc758\ud558\uae30"\uc5d0\uc11c \uc774\ub984 \ub610\ub294 \ubcc4\uce6d, \ub2f5\uc7a5 \ubc1b\uc744 \uc774\uba54\uc77c, \ubb38\uc758 \uc885\ub958\uc640 \ub0b4\uc6a9\uc744 \uc9c1\uc811 \uc801\uc5b4 \ubcf4\ub0bc \uc218 \uc788\uc5b4\uc694. \ubcf4\ub0b4\uae30\ub97c \ub204\ub974\uace0 \ubcf4\uc548 \ud655\uc778\uc744 \ub9c8\uce5c \uacbd\uc6b0\uc5d0\ub9cc \uc36c\uc6cd\uc2a4 \uc9c0\uc6d0 \uc774\uba54\uc77c(support@sunworks.kr)\ub85c \uc804\ub2ec\ub3fc\uc694.',"\ud559\uc2b5 \uae30\ub85d\uc740 \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694. \uc571 \ubc84\uc804\uacfc \ub370\uc774\ud130 \ubc84\uc804 \uac19\uc740 \uc9c4\ub2e8 \uc815\ubcf4\ub294 \uae30\ubcf8\uc73c\ub85c \uaebc\uc838 \uc788\uace0, \ud568\uaed8 \ubcf4\ub0b4\uae30\ub97c \uc9c1\uc811 \uc120\ud0dd\ud55c \uacbd\uc6b0\uc5d0\ub9cc \ubb38\uc758 \ubcf8\ubb38\uc5d0 \ub4e4\uc5b4\uac00\uc694.","\ubb38\uc758 \uc804\ub2ec\uacfc \uc2a4\ud338 \ubc29\uc9c0\uc5d0\ub294 Cloudflare Workers\xb7Turnstile, Resend, Google Workspace\ub97c \uc774\uc6a9\ud558\uba70 \uad6d\uc678\uc5d0\uc11c \ucc98\ub9ac\ub420 \uc218 \uc788\uc5b4\uc694. \ubd07\xb7\uc911\ubcf5\xb7\uacfc\ub3c4\ud55c \ubc1c\uc1a1 \ubc29\uc9c0\ub97c \uc704\ud574 IP\xb7\uc774\uba54\uc77c \ud574\uc2dc\uc640 \uc694\uccad \uc2dd\ubcc4\uc815\ubcf4\ub97c \uc77c\uc2dc\uc801\uc73c\ub85c \ucc98\ub9ac\ud574\uc694. \ud574\uc2dc\ub3c4 \uac1c\uc778\uc815\ubcf4\ub85c \ucde8\uae09\ud574\uc694.","\ubb38\uc758\uc5d0 \ud544\uc694\ud55c \uc815\ubcf4\ub9cc \uc801\uace0 \ubbfc\uac10\uc815\ubcf4\ub294 \ubcf4\ub0b4\uc9c0 \ub9c8\uc138\uc694. \ub9cc 14\uc138 \ubbf8\ub9cc \uc5b4\ub9b0\uc774\uc758 \uac1c\uc778\uc815\ubcf4\uac00 \ud3ec\ud568\ub41c \ubb38\uc758\ub294 \ubcf4\ud638\uc790\uac00 \ub300\uc2e0 \ubcf4\ub0b4 \uc8fc\uc138\uc694.","\uc811\uc218 \uacb0\uacfc\uac00 \ubd88\ud655\uc2e4\ud558\uba74 \uc774 \ud654\uba74\uc5d0\uc11c \ubcf4\uc548 \ud655\uc778 \ud6c4 \uac19\uc740 \ub0b4\uc6a9\uc73c\ub85c \ub2e4\uc2dc \ubcf4\ub0b4 \uc8fc\uc138\uc694. \uc0c8\ub85c \uc791\uc131\ud558\uba74 \uc911\ubcf5 \uc811\uc218\ub420 \uc218 \uc788\uc5b4\uc694. \uacc4\uc18d \uc2e4\ud328\ud558\uac70\ub098 \uc0ad\uc81c\ub97c \ubb38\uc758\ud558\ub824\uba74 support@sunworks.kr\ub85c \uc54c\ub824 \uc8fc\uc138\uc694.","\ubc1b\uc740 \uc758\uacac\uacfc \uc774\uba54\uc77c\uc740 \ub2f5\ubcc0\uacfc \uc571 \uac1c\uc120\uc5d0\ub9cc \uc368\uc694. \uba54\uc77c\ud568\uacfc \uc81c\uacf5\uc790\uc758 \ubcf4\uad00\xb7\uc0ad\uc81c \uae30\uac04\uc740 \ubcc4\ub3c4 \uc6b4\uc601 \uc815\ucc45\uc73c\ub85c \uc815\ud560 \uc608\uc815\uc774\uc5d0\uc694."],t.s)
B.aHw=new A.em("10. \uc758\uacac \ubcf4\ub0b4\uae30",B.abJ)
B.ahQ=s(["\uac1c\uc778\uc815\ubcf4\uc640 \uad00\ub828\ud574 \ubb3b\uace0 \uc2f6\uc740 \uac83\uc774 \uc788\uc73c\uba74 \uc544\ub798\ub85c \uc54c\ub824 \uc8fc\uc138\uc694.","\xb7 \uc6b4\uc601: \uc36c\uc6cd\uc2a4","\xb7 \ud68c\uc0ac \ud648\ud398\uc774\uc9c0: https://www.sunworks.kr","\xb7 \uacf5\uc2dd \uc571 \uc18c\uac1c: https://hanja.sunw.kr/","\xb7 \uc774\uba54\uc77c: support@sunworks.kr","\xb7 \uc804\ud654: 070-8717-8850","\xb7 \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ucc45\uc784\uc790: \ub0a8\uc120(\ub300\ud45c)",'\uc571 \uc548\uc758 "\uc774\uc0c1\ud574\uc694" \ubc84\ud2bc(\ubb38\ud56d \uc2e0\uace0)\uc73c\ub85c\ub3c4 \uc54c\ub824 \uc904 \uc218 \uc788\uc5b4\uc694. \uc2e0\uace0\ub294 \uc758\uacac \ubcf4\ub0b4\uae30\uc640 \uac19\uc740 \uacbd\ub85c(Cloudflare\xb7Resend)\ub85c \ubcf4\uc548 \ud655\uc778\uc744 \uac70\uccd0 \uc36c\uc6cd\uc2a4 \uc9c0\uc6d0\ud300 \uba54\uc77c\ud568\uc73c\ub85c \uc804\ub2ec\ub3fc\uc694. \uc2e0\uace0\uc5d0\ub294 \uc5b4\ub5a4 \ud55c\uc790\ub098 \ub0b1\ub9d0\uc778\uc9c0, \ubb38\uc81c \uc885\ub958, \uace0\ub978 \uc0ac\uc720, \uc9c1\uc811 \uc801\uc740 \ub0b4\uc6a9(\uc120\ud0dd), \uc571\xb7\ub370\uc774\ud130 \ubc84\uc804, \uc2e0\uace0\ud55c \uc2dc\uac01\ub9cc \ub4e4\uc5b4\uac00\uc694. \uc774\ub984\uc774\ub098 \uc5f0\ub77d\ucc98\ub294 \ubc1b\uc9c0 \uc54a\uc73c\ub2c8 \uc801\ub294 \uce78\uc5d0\ub3c4 \uac1c\uc778\uc815\ubcf4\ub294 \uc4f0\uc9c0 \ub9c8\uc138\uc694. \uc804\ub2ec\uacfc \ubcf4\uad00\uc740 10\uc808 \uc758\uacac \ubcf4\ub0b4\uae30\uc640 \uac19\uc740 \ubc29\uc2dd\uc774\uc5d0\uc694.'],t.s)
B.aHv=new A.em("11. \uad81\uae08\ud55c \uc810\uc774 \uc788\uc73c\uba74",B.ahQ)
B.ayy=s(["\xb7 1.0 (2026\ub144 9\uc6d4 8\uc77c \uc2dc\ud589) \u2014 \ucc98\uc74c \ub9cc\ub4e4\uc5c8\uc5b4\uc694.","\xb7 1.1 (2026\ub144 9\uc6d4 26\uc77c \uc2dc\ud589) \u2014 \uc5f0\uad6c \ucc38\uc5ec(\uc120\ud0dd) \uc808\uc744 \ub354\ud588\uc5b4\uc694.","\xb7 1.2 (2026\ub144 10\uc6d4 2\uc77c \uc2dc\ud589) \u2014 \uc6b4\uc601 \ud68c\uc0ac\uc640 \uacf5\uc2dd \uc0ac\uc774\ud2b8, \ubb38\uc758 \uc774\uba54\uc77c\uc744 \uc548\ub0b4\ud588\uc5b4\uc694.","\xb7 1.3 (2026\ub144 10\uc6d4 11\uc77c \uc2dc\ud589) \u2014 \uc758\uacac \ubcf4\ub0b4\uae30 \uc808\uc744 \ub354\ud588\uc5b4\uc694.","\xb7 1.4 (2026\ub144 10\uc6d4 16\uc77c \uc2dc\ud589) \u2014 \uc804\ud654\ubc88\ud638\uc640 \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ucc45\uc784\uc790\ub97c \uc548\ub0b4\ud588\uc5b4\uc694.","\ubc29\uce68\uc744 \uace0\uce60 \ub54c\ub294 \uc571 \uc548\uc758 \uc774 \ud654\uba74\uacfc \uc6f9 \ud398\uc774\uc9c0\ub97c \ud568\uaed8 \uace0\uce58\uace0, \ubc14\ub010 \ub0a0\uc9dc\ub97c \uc5ec\uae30\uc5d0 \uc801\uc744\uac8c\uc694."],t.s)
